import type { EditorFacts, EditorSettings } from "../../contracts/editor.ts";

/** The line a generated file starts with. A file without it is a person's. */
export const MARK = "# Generated by Ropes";
const LEGACY_MARK = "# Generated by Cinch";

export const isMarked = (text: string): boolean =>
  text.startsWith(LEGACY_MARK) || text.startsWith(`${MARK} from \`[editor]\``);

const HEADER = [
  `${MARK} from \`[editor]\` in the Ropes config. Do not edit this file:`,
  "# `rope doctor --fix` rewrites it.",
  "root = true",
];

/** In the order the file lists them. The left side is the file's own key. */
const lines = (facts: EditorFacts): string[] =>
  [
    ["charset", facts.charset],
    ["indent_style", facts.indent_style],
    ["indent_size", facts.indent_size],
    ["end_of_line", facts.end_of_line],
    ["insert_final_newline", facts.final_newline],
    ["trim_trailing_whitespace", facts.trim_trailing_whitespace],
    ["max_line_length", facts.line_width],
  ].flatMap(([key, value]) =>
    value === undefined ? [] : [`${key} = ${value}`]
  );

const section = (glob: string, facts: EditorFacts): string[] => {
  const body = lines(facts);
  return body.length === 0 ? [] : ["", `[${glob}]`, ...body];
};

/**
 * The whole file. The format has no list of globs that is safe for every
 * glob, so an override with several gets one section for each.
 */
export const render = (settings: EditorSettings): string =>
  [
    ...HEADER,
    ...section("*", settings),
    ...(settings.overrides ?? []).flatMap((override) =>
      override.files.flatMap((glob) => section(glob, override))
    ),
    "",
  ].join("\n");
